import React, { useState } from 'react';
import { View, Text, StyleSheet, TextInput, TouchableOpacity, ScrollView, FlatList } from 'react-native';

export default function SupportScreen({ onBack }) {
  const [activeTab, setActiveTab] = useState('complaint'); // 'complaint' or 'chat'
    
      // الشكاوى
        const [subject, setSubject] = useState('');
          const [details, setDetails] = useState('');
            const [submitted, setSubmitted] = useState(false);

              // المحادثات
                const [messages, setMessages] = useState([
                    { id: '1', sender: 'support', text: 'أهلاً بك في الدعم الفني لتطبيق احجز وملعب ⚽ كيف يمكننا مساعدتك اليوم؟' }
                      ]);
                        const [inputMsg, setInputMsg] = useState('');

                          const handleSendComplaint = () => {
                              if (!subject || !details) return;
                                  setSubmitted(true);
                                      setTimeout(() => {
                                            setSubmitted(false);
                                                  setSubject('');
                                                        setDetails('');
                                                              alert('تم إرسال الشكوى بنجاح وسيتم الرد عليك قريباً');
                                                                  }, 1000);
                                                                    };

                                                                      const handleSendMessage = () => {
                                                                          if (!inputMsg.trim()) return;
                                                                              const newMsg = { id: Date.now().toString(), sender: 'user', text: inputMsg };
                                                                                  setMessages((prev) => [...prev, newMsg]);
                                                                                      setInputMsg('');

                                                                                          // رد تلقائي محاكى من الدعم
                                                                                              setTimeout(() => {
                                                                                                    setMessages((prev) => [
                                                                                                            ...prev,
                                                                                                                    { id: (Date.now() + 1).toString(), sender: 'support', text: 'شكراً لتواصلك معنا، كادر الدعم يتفقد رسالتك الآن.' }
                                                                                                                          ]);
                                                                                                                              }, 1200);
                                                                                                                                };

                                                                                                                                  return (
                                                                                                                                      <View style={styles.container}>
                                                                                                                                            <View style={styles.header}>
                                                                                                                                                    <Text style={styles.title}>الدعم الفني والمحادثات 🎧</Text>
                                                                                                                                                          </View>

                                                                                                                                                                {/* التبديل بين الشكاوى والمحادثة */}
                                                                                                                                                                      <View style={styles.tabContainer}>
                                                                                                                                                                              <TouchableOpacity
                                                                                                                                                                                        style={[styles.tabButton, activeTab === 'complaint' && styles.activeTab]}
                                                                                                                                                                                                  onPress={() => setActiveTab('complaint')}
                                                                                                                                                                                                          >
                                                                                                                                                                                                                    <Text style={[styles.tabText, activeTab === 'complaint' && styles.activeTabText]}>تقديم شكوى</Text>
                                                                                                                                                                                                                            </TouchableOpacity>
                                                                                                                                                                                                                                    <TouchableOpacity
                                                                                                                                                                                                                                              style={[styles.tabButton, activeTab === 'chat' && styles.activeTab]}
                                                                                                                                                                                                                                                        onPress={() => setActiveTab('chat')}
                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                          <Text style={[styles.tabText, activeTab === 'chat' && styles.activeTabText]}>محادثة مباشرة</Text>
                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                        </View>

                                                                                                                                                                                                                                                                                              {/* قسم تقديم شكوى */}
                                                                                                                                                                                                                                                                                                    {activeTab === 'complaint' ? (
                                                                                                                                                                                                                                                                                                            <ScrollView style={styles.content}>
                                                                                                                                                                                                                                                                                                                      <Text style={styles.label}>عنوان الشكوى / المشكلة:</Text>
                                                                                                                                                                                                                                                                                                                                <TextInput
                                                                                                                                                                                                                                                                                                                                            style={styles.input}
                                                                                                                                                                                                                                                                                                                                                        placeholder="مثال: مشكلة في الإنارة، تأخير فتح الملعب..."
                                                                                                                                                                                                                                                                                                                                                                    placeholderTextColor="#94a3b8"
                                                                                                                                                                                                                                                                                                                                                                                value={subject}
                                                                                                                                                                                                                                                                                                                                                                                            onChangeText={setSubject}
                                                                                                                                                                                                                                                                                                                                                                                                      />

                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={styles.label}>تفاصيل الشكوى:</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                          <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                      style={[styles.input, styles.textArea]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="اكتب التفاصيل هنا..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholderTextColor="#94a3b8"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          multiline
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      numberOfLines={4}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={details}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChangeText={setDetails}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={[styles.submitButton, (!subject || !details) && styles.disabledButton]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          disabled={!subject || !details}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onPress={handleSendComplaint}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={styles.submitText}>إرسال الشكوى</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* قسم المحادثات المباشرة */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={styles.chatContainer}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data={messages}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  contentContainerStyle={styles.chatList}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              styles.msgBubble,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item.sender === 'user' ? styles.userMsg : styles.supportMsg
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={item.sender === 'user' ? styles.userMsgText : styles.supportMsgText}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {item.text}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.chatInputBox}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={styles.sendBtn} onPress={handleSendMessage}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={styles.sendBtnText}>إرسال</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={styles.chatInput}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="اكتب رسالتك..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          placeholderTextColor="#94a3b8"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={inputMsg}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChangeText={setInputMsg}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity style={styles.backButton} onPress={onBack}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={styles.backText}>العودة للرئيسية</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      container: { flex: 1, backgroundColor: '#f8f9fa' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        header: { padding: 16, paddingTop: 40, backgroundColor: '#ffffff', borderBottomWidth: 1, borderColor: '#e2e8f0' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title: { fontSize: 18, fontWeight: 'bold', textAlign: 'right', color: '#0f172a' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tabContainer: { flexDirection: 'row-reverse', backgroundColor: '#e2e8f0', margin: 12, borderRadius: 8, padding: 3 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              tabButton: { flex: 1, paddingVertical: 10, alignItems: 'center', borderRadius: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                activeTab: { backgroundColor: '#ffffff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tabText: { fontSize: 13, color: '#64748b', fontWeight: 'bold' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    activeTabText: { color: '#2563eb' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      content: { padding: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label: { fontSize: 13, fontWeight: 'bold', color: '#334155', textAlign: 'right', marginBottom: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          input: { backgroundColor: '#ffffff', borderWidth: 1, borderColor: '#cbd5e1', borderRadius: 8, padding: 10, textAlign: 'right', marginBottom: 14 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            textArea: { height: 100, textAlignVertical: 'top' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              submitButton: { backgroundColor: '#ef4444', padding: 14, borderRadius: 8, alignItems: 'center', marginTop: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                disabledButton: { backgroundColor: '#cbd5e1' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  submitText: { color: '#ffffff', fontWeight: 'bold' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    chatContainer: { flex: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      chatList: { padding: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        msgBubble: { padding: 10, borderRadius: 10, marginBottom: 10, maxWidth: '80%' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          userMsg: { backgroundColor: '#2563eb', alignSelf: 'flex-start' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            supportMsg: { backgroundColor: '#e2e8f0', alignSelf: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              userMsgText: { color: '#ffffff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                supportMsgText: { color: '#0f172a' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  chatInputBox: { flexDirection: 'row-reverse', padding: 10, backgroundColor: '#ffffff', borderTopWidth: 1, borderColor: '#e2e8f0' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    chatInput: { flex: 1, backgroundColor: '#f1f5f9', borderRadius: 20, paddingHorizontal: 14, textAlign: 'right', marginRight: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      sendBtn: { backgroundColor: '#2563eb', borderRadius: 20, paddingHorizontal: 16, justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendBtnText: { color: '#ffffff', fontWeight: 'bold' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          backButton: { backgroundColor: '#2563eb', padding: 12, margin: 12, borderRadius: 8, alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            backText: { color: '#ffffff', fontWeight: 'bold' }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            